package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.Dungeon;
import com.shatteredpixel.shatteredpixeldungeon.items.trinkets.*;

/** Uses pure level-indexed rules, never floor-feeling selectors, damage rolls or gas generation. */
public final class TrinketExplanation {
    private TrinketExplanation(){}
    private static String n(float value){return ObfuscationExplanation.number(value);}
    private static String percent(float chance){return n(100*Math.min(1,Math.max(0,chance)))+"%";}
    public static String details(Trinket trinket){
        if(!trinket.isIdentified())return "_Trinket calculations_\nIdentify this trinket before its current upgrade-dependent results are shown. Inspection does not activate it or infer its hidden level.";
        int level=trinket.buffedLvl();String text;
        if(trinket instanceof EyeOfNewt)text="Normal vision-distance input is multiplied by 0.875 − 0.125 × level = "+n(EyeOfNewt.visionRangeMultiplier(level))+". Nearby monster sensing supplies a separate range of 2 + level = "+EyeOfNewt.mindVisionRange(level)+" tiles. These ranges do not simply add, and sensing does not make walls transparent for projectiles or discover secret doors. Other vision modifiers, rounding, visibility and excluded monsters keep their existing rules.";
        else if(trinket instanceof FerretTuft)text="Every supported defender's evasion roll, including enemies as well as the hero, is multiplied by 1 + 0.125 × (level + 1) = "+n(FerretTuft.evasionMultiplier(level))+". This is a score multiplier, not that percentage chance to dodge an attack. The final contest also depends on the attacker's accuracy and other conditions; special guaranteed-hit/evasion paths have separate rules.";
        else if(trinket instanceof SaltCube)text="Hunger gain is multiplied by 1 / (1 + 0.25 × (level + 1)) = "+n(SaltCube.hungerGainMultiplier(level))+". An unchanged hunger reserve therefore lasts "+n(1/SaltCube.hungerGainMultiplier(level))+" times as long under that step, rather than gaining extra food energy. Natural health-regeneration rate is separately multiplied by "+n(SaltCube.healthRegenMultiplier(level))+"; its unchanged recovery interval is divided by that factor. This is a tradeoff between two rates, not an equal percentage change to healing potions or maximum HP.";
        else if(trinket instanceof VialOfBlood)text="Supported burst healing's total is multiplied by 1 + 0.125 × (level + 1) = "+n(VialOfBlood.totalHealMultiplier(level))+" and delivered through the existing delayed-healing path. "+(Dungeon.hero==null?"The per-update cap depends on maximum HP and the Vial's level.":"At current maximum HP, the Vial's per-update base healing offer cap is "+VialOfBlood.maxHealPerTurn(level)+" HP.")+" The cap is not the total healing pool or a guarantee of that much health each turn: missing HP, remaining healing and run healing modifiers still apply. Dew-to-shield allocation retains its separate rules.";
        else if(trinket instanceof ExoticCrystals)text="For supported generated consumables other than the special Healing conversion rule, the regular-to-exotic check is 0.2 + 0.2 × level = "+percent(ExoticCrystals.consumableExoticChance(level))+". This replaces the generated consumable with its counterpart rather than adding another item or improving every potion effect. Healing-to-Shielding instead uses APD's current explicit conversion setting: "+percent(ExoticCrystals.consumableExoticChance(com.shatteredpixel.shatteredpixeldungeon.items.potions.PotionOfHealing.class))+". A zero setting does not gain an additional crystal chance for that conversion. Already existing items and other supported generation paths keep their explicit rules.";
        else if(trinket instanceof RatSkull)text="Supported rare enemy-variant chances are multiplied by 2 + level = "+n(RatSkull.exoticChanceMultiplier(level))+". Each enemy keeps its own base chance, eligibility and comparison limit; this is not a universal final spawn percentage or a multiplier for every enemy's number, damage or loot. For crystal mimics and armored statues, only the increase above the ordinary chance is halved. Their effective factor at this level is "+n((RatSkull.exoticChanceMultiplier(level)+1)/2f)+". It does not retroactively transform monsters already generated.";
        else if(trinket instanceof MimicTooth)text="Supported ordinary mimic chances use factor 1.5 + 0.5 × level = "+n(MimicTooth.mimicChanceMultiplier(level))+". The separate ebony-mimic check is 0.125 + 0.125 × level = "+percent(MimicTooth.ebonyMimicChance(level))+". These apply to their stated generation opportunities, not to every tile or every existing chest. The tooth also uses its existing stealthy-mimic behavior; ordinary sensing can exclude disguised neutral mimics. Inspection does not locate hidden mimics.";
        else if(trinket instanceof ParchmentScrap)text="Supported enchantment-generation chances use factor "+n(ParchmentScrap.enchantChanceMultiplier(level))+", while supported curse-generation chances separately use factor "+n(ParchmentScrap.curseChanceMultiplier(level))+". The two factors apply to their respective generation checks, not an added final percentage on every item or a guarantee that a particular unidentified item is enchanted or cursed. Each source keeps its base chance and eligible outcomes. This does not multiply the strength of an enchantment already on equipment.";
        else if(trinket instanceof PetrifiedSeed)text="Eligible grass seed outcomes use a seed-to-runestone replacement check of "+percent(PetrifiedSeed.stoneInsteadOfSeedChance(level))+". The grass-loot input separately uses factor "+n(PetrifiedSeed.grassLootMultiplier(level))+". These are separate stages, not a guarantee of that percentage runestones per grass tile: grass must first produce eligible loot under its normal rules. Dew, seeds and stones remain separate outcomes and retain the existing automatic-pickup safeguards.";
        else if(trinket instanceof ThirteenLeafClover){float chance=ThirteenLeafClover.alterHeroDamageChance(level);text="A supported hero damage roll has a "+percent(chance)+" chance to use the clover's extreme-roll branch. Within that branch, the maximum wins 60% of checks and the minimum 40%. At this level those branches account for "+percent(.6f*chance)+" and "+percent(.4f*chance)+" of all eligible rolls. The remaining rolls keep the ordinary distribution. These are input-roll outcomes before other modifiers and defenses, not guaranteed final HP loss or a 60% critical-hit chance on every attack.";}
        else if(trinket instanceof DimensionalSundial)text="Enemy respawn timing divides its ordinary cooldown by the current time-of-day spawn factor. Daytime uses "+n(DimensionalSundial.enemySpawnMultiplierDaytime(level))+" and nighttime uses "+n(DimensionalSundial.enemySpawnMultiplierNighttime(level))+". A factor above one shortens the interval; below one lengthens it. This is a rate change, not that many enemies guaranteed per turn. Existing population limits, spawn-cell checks, floor rules and custom resource modifiers still apply. Inspection does not advance time or choose a time-of-day outcome.";
        else if(trinket instanceof CrackedSpyglass){float extra=CrackedSpyglass.extraLootChance(level);text="An eligible regular-floor generation attempts floor(U + "+n(extra)+") extra hidden item placements, where U is a uniform random fraction from 0 inclusive to 1 exclusive. The expected count input is 0.375 × (level + 1) = "+n(extra)+" items per eligible floor: whole items plus a fractional chance of one more. This is not a percentage multiplier for every enemy drop or a guarantee of one item on each floor. Existing drop-cell and item-generation rules determine the actual contents and placements. No hidden location is revealed by inspection.";}
        else if(trinket instanceof MossyClump)text="When the normal-floor branch of eligible feeling generation is reached, its override threshold is 0.25 + 0.25 × level = "+percent(MossyClump.overrideNormalLevelChance(level))+". Its existing saved selector chooses between the supported water and grass feelings. This is conditional on that normal branch, not the final chance of every generated floor being altered, and it does not rebuild an already generated floor. Inspection never advances the selector.";
        else if(trinket instanceof TrapMechanism)text="When the normal-floor branch of eligible feeling generation is reached, its override threshold is "+percent(TrapMechanism.overrideNormalLevelChance(level))+". Separately, supported hidden-trap painting has a "+percent(TrapMechanism.revealHiddenTrapChance(level))+" reveal threshold. These are two different conditional checks, not the probability of discovering a hidden door by searching. Existing painting, room and floor restrictions still apply; inspection does not generate traps or advance the saved feeling selector.";
        else if(trinket instanceof ChaoticCenser)text="The gas schedule's average interval input is integer division 300 / (level + 1) = "+ChaoticCenser.averageTurnsUntilGas(level)+" game-time units. Actual scheduling varies around this input and can defer release when its existing conditions do not permit gas. It is not a fixed countdown to the next cloud or real-world seconds. Cloud type, quantity, terrain and challenge restrictions keep their own rules; inspection does not roll a cloud or alter its pending schedule.";
        else if(trinket instanceof WondrousResin)text="The ordinary chance for supported cursed-wand effect selection to force its positive branch is "+percent(WondrousResin.positiveCurseEffectChance(level))+". Its separate extra cursed-effect threshold is "+percent(WondrousResin.extraCurseEffectChance(level))+". Each chosen effect keeps its own target, resistance and outcome rules, so a positive selection is not a universal healing or damage amount. Existing temporary force-positive effects can override selection. Inspection does not select or apply a cursed effect.";
        else if(trinket instanceof ShardOfOblivion)text="Passive identification is suppressed while the supported Shard effect applies; eligible items can instead become ready for deliberate identification. The ordinary loot-chance factor adds 0.2 per counted unidentified equipment/use contribution, capped at level + 1 = "+(level+1)+" contributions. This is an added factor applied to a monster's base ordinary loot chance, not that many percentage points added to every final drop chance. "+(Dungeon.hero==null?"":"Current public-state factor under the Shard's contribution rules: "+n(ShardOfOblivion.lootChanceMultiplier(level))+". ")+"Wand and thrown-use trackers keep their own eligibility and duration rules. No item's hidden level, curse or enchantment is examined to compute this description.";
        else return "";
        return "_Current trinket calculation_\nKnown effective trinket level: "+level+". "+text+" Upgrading changes the level-indexed values under these same rules; it does not remove the stated conditions or caps.";
    }
}
